<?php
require_once(__DIR__.'/../init.php'); require_once('util/scheduler.php'); class common_config { public function createSession () { $settings = getSessionValue('settingsApp'); if (!$settings) { setSessionValue('settingsApp', $settings = readJsonSettings('settings_app', false)); } return [ 'session' => getSessionValue('session'), 'settings' => $settings ]; } public function readExtraSettings ($params) { return readExtraSettings(null, $params->name); } public function updateExtraSettings ($params) { return Scheduler::writeExtraSettings(null, $params->name, $params->value, !empty($params->scheduleSetup)); } public function readConfigs() { $ret = []; $ini = readConfigJson(); foreach ($ini as $k => $v) { if (!empty($v['app'])) { $cfg = getTestedAppConfig($v['app'], $k); if (!empty($cfg['configTitle'])) { $ret[] = [ 'config' => $k, 'app' => $cfg['app'], 'title' => $cfg['configTitle'], 'theme' => empty($cfg['theme']) ? 'maptheme' : $cfg['theme'], 'css' => empty($cfg['css']) ? null : $cfg['css'] ]; } } } if (empty($ret)) { throw new Exception("Отсутствуют настройки конфигураций. Обратитесь к администратору."); } return $ret; } public function getConfigs () { $configs = $this->readConfigs(); $ret = []; foreach ($configs as $v) { $row = ['cfg' => $v['config'], 'name' => $v['title'], 'app' => $v['app']]; $ret[] = $row; } return $ret; } public function check ($params = null) { $params = $params ?: new stdClass(); $app = getSessionValue('app'); $config = getSessionValue('config'); $cfg = getTestedAppConfig($app, $config); if (empty($cfg)) { throw new Exception("Задача \"$app\" ограничена конфигурацией сервера. Обратитесь к Администратору"); } if (empty(getSessionValue('exdata'))) { setSessionValue('appConfig', $cfg, 'mapUserCode', null); } else { setSessionValue('appConfig', $cfg); } loadMainService(); if (isset($cfg['https']) && !empty($cfg['https'])) { TestHTTPS(); } $clearCfg = $cfg; unsetAppConfigBackend($clearCfg); $versions = (object) [ 'server' => '' ]; $errors = ''; if (!empty($params->needVersions)) { $fileVersion = __DIR__ . '/../../../../version'; if (file_exists($fileVersion)) { $versions = json_clean_decode(file_get_contents($fileVersion)); $need = isset($versions->map) ? $versions->map : ''; unset($versions->map); } if (!empty($cfg['mapBin'])) { $mapVersion = realpath($cfg['mapBin']) . '/version'; if (!file_exists($mapVersion)) { $errors .= "Отсутствует файл версии комплекса МАП <b>version</b>.<br>"; } else { $versions->map = trim(file_get_contents($mapVersion)); if (compareVersions($versions->map, $need) < 0) { $errors .= "Требуется версия комплекса МАП <b>$need и выше</b>." . " Текущая версия <b>$versions->map</b>.<br><br>"; } } } if (!empty($cfg['connect'])) { $db = connectDb(); if (isColumnExists($db, 'syssetup', 'databaseversion')) { $versions->database = (string)selectSqlValue($db, "SELECT doubletostr(databaseversion) || '.' || databasesubversion FROM syssetup WHERE syssetupcode = 1"); } $versions->postgresql = (string)selectSqlValue($db, "SELECT array_to_string(numbers[1 : array_upper(numbers,1) -1], '.')
                        FROM (SELECT string_to_array(current_setting('server_version'), '.') numbers) n"); } } setSessionValue('versions', $versions); if ($errors) { throw new Exception($errors); } return [ 'appConfig' => $clearCfg, 'versions' => $versions, ]; } public function getCurrentConfig() { $ret = getSessionValue('appConfig'); unset($ret['connect']); return $ret; } } handleJsonRpc('common_config');